//! The whole generation: extract every release, merge, check bundling, write data and report.

use std::fmt::Write as _;

use bleedthrough_builtins::format::write as format_write;
use bleedthrough_builtins::{BuiltinData, Kind};
use bleedthrough_syntax::ParserBackend;

use crate::bundling::Bundling;
use crate::conflicts::Conflicts;
use crate::merge::merge;
use crate::release::{NamedRelease, extract_release};

/// The two generated files.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Generated {
    /// Contents of `stubs/builtin.data`.
    pub data: String,
    /// Contents of `stubs/coverage.txt`.
    pub coverage: String,
}

/// Generates the data and the coverage report from vendored stubs only.
///
/// `releases` pairs each input with its directory name (for example `php-8.5.11`).
pub fn generate(
    backend: &dyn ParserBackend,
    releases: &[NamedRelease],
    conflicts_text: &str,
    bundling_text: &str,
) -> Result<Generated, Vec<String>> {
    let mut conflicts = Conflicts::parse(conflicts_text).map_err(|e| vec![e])?;
    let bundling = Bundling::parse(bundling_text).map_err(|e| vec![e])?;

    let mut problems = Vec::new();
    let mut extracted = Vec::new();
    let mut report = String::new();
    let _ = writeln!(
        report,
        "Coverage of the built-in data generation. Generated by `cargo xtask gen-builtins`; do not edit."
    );
    let _ = writeln!(
        report,
        "Parser backend: {} {}",
        backend.info().name,
        backend.info().version
    );
    for (name, input) in releases {
        let out = extract_release(backend, input);
        problems.extend(out.errors.iter().map(ToString::to_string));
        write_release_report(&mut report, name, &out);
        extracted.push((input.version, out.items));
    }
    if !problems.is_empty() {
        return Err(problems);
    }

    let (records, merge_report) = merge(extracted, &mut conflicts)
        .map_err(|errors| errors.iter().map(ToString::to_string).collect::<Vec<_>>())?;

    problems.extend(bundling_problems(&bundling, &records));
    if !problems.is_empty() {
        return Err(problems);
    }

    let total = records.len();
    let data = BuiltinData::new(bundling.records(), records)
        .map_err(|e| vec![format!("the merged data is invalid: {e}")])?;
    let text = format_write(&data);

    let _ = writeln!(report, "\n== Merge");
    let _ = writeln!(report, "records: {total}");
    let _ = writeln!(
        report,
        "symbols declared more than once in a version and merged: {}",
        merge_report.merged_declarations
    );
    for entry in conflicts.used() {
        let _ = writeln!(
            report,
            "conflict resolved: {} {} ({})",
            entry.kind.as_str(),
            entry.name,
            entry.reason
        );
    }
    let _ = writeln!(
        report,
        "alias targets that name no record: {}",
        merge_report.unresolved_aliases.len()
    );
    for alias in &merge_report.unresolved_aliases {
        let _ = writeln!(report, "  {alias}");
    }
    let _ = writeln!(report, "\n== Bundling");
    for entry in &bundling.extensions {
        let _ = writeln!(
            report,
            "{}: unbundled {} ({})",
            entry.name, entry.unbundled, entry.source
        );
    }
    Ok(Generated {
        data: text,
        coverage: report,
    })
}

fn write_release_report(report: &mut String, name: &str, out: &crate::release::ReleaseExtraction) {
    let _ = writeln!(report, "\n== {name}");
    let excluded: Vec<_> = out.files.iter().filter(|f| f.excluded.is_some()).collect();
    let _ = writeln!(
        report,
        "stub files: {}, excluded: {}, records: {}",
        out.files.len(),
        excluded.len(),
        out.items.len()
    );
    for file in excluded {
        if let Some(rule) = file.excluded {
            let _ = writeln!(
                report,
                "excluded {} ({}: {})",
                file.path, rule.directory, rule.reason
            );
        }
    }
    for file in out.files.iter().filter(|f| f.excluded.is_none()) {
        let mut line = format!("{}:", file.path);
        for kind in Kind::ALL {
            let found = file.coverage.found.get(&kind).copied().unwrap_or(0);
            let produced = file.coverage.produced.get(&kind).copied().unwrap_or(0);
            if found != 0 || produced != 0 {
                let _ = write!(line, " {}={found}/{produced}", kind.as_str());
            }
        }
        let _ = writeln!(report, "{line}");
    }
}

/// Extensions the bundling file calls unbundled must have no stubs in those versions.
fn bundling_problems(
    bundling: &Bundling,
    records: &[bleedthrough_builtins::Record],
) -> Vec<String> {
    let mut problems = Vec::new();
    for entry in &bundling.extensions {
        if let Some(record) = records
            .iter()
            .find(|r| r.extension == entry.name && r.mask.overlaps(entry.unbundled))
        {
            problems.push(format!(
                "stubs/bundling.toml says `{}` is unbundled in {}, but {} `{}` has stubs in {}",
                entry.name,
                entry.unbundled,
                record.kind().as_str(),
                record.name,
                record.mask
            ));
        }
    }
    problems
}
